const base64Audio = $json.data?.message?.base64 || $json.body?.data?.message?.base64;

if (!base64Audio) {
  throw new Error("Áudio em Base64 não encontrado no payload recebido. Verifique o node anterior.");
}

const buffer = Buffer.from(base64Audio, 'base64');

return [
  {
    json: {
      status: "ok",
      mensagem: "Áudio convertido com sucesso"
    },
    binary: {
      data: {
        data: buffer,
        mimeType: 'audio/ogg',
        fileName: 'audio.ogg'
      }
    }
  }
];
